pub fn concat(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    let total_len = a
        .len()
        .checked_add(b.len())
        .expect("length overflow when concatenating vectors");

    let mut c = Vec::with_capacity(total_len);
    c.extend(a.into_iter());
    c.extend(b.into_iter());
    c
}

